 235	  /**
 236	   * Split text into overlapping chunks.
 237	   * Tries to split at paragraph/sentence boundaries when possible.
 238	   */
 239	  chunkText(text: string): string[] {
 240	    if (text.length <= this.chunkSize) return [text];
 241	
 242	    const chunks: string[] = [];
 243	    let start = 0;
 244	
 245	    while (start < text.length) {
 246	      let end = Math.min(start + this.chunkSize, text.length);
 247	
 248	      // Try to find a natural break point (paragraph or sentence)
 249	      if (end < text.length) {
 250	        const slice = text.slice(start, end);
 251	        const paragraphBreak = slice.lastIndexOf("\n\n");
 252	        const sentenceBreak = slice.lastIndexOf(". ");
 253	
 254	        if (paragraphBreak > this.chunkSize * 0.5) {
 255	          end = start + paragraphBreak + 2;
 256	        } else if (sentenceBreak > this.chunkSize * 0.5) {
 257	          end = start + sentenceBreak + 2;
 258	        }
 259	      }
 260	
 261	      chunks.push(text.slice(start, end).trim());
 262	
 263	      // Move start forward, accounting for overlap
 264	      const nextStart = end - this.chunkOverlap;
 265	      if (nextStart <= start) {
 266	        // Prevent infinite loop: force advance
 267	        start = end;
 268	      } else {
 269	        start = nextStart;
 270	      }
 271	    }
 272	
 273	    return chunks.filter((c) => c.length > 0);
 274	  }
